const express = require('express');
const cors = require('cors');
const http = require('http');
const rateLimit = require('express-rate-limit');
const { createDb } = require('./db');
const { authMiddleware } = require('./middleware/auth');
const { createAuthRouter } = require('./routes/auth');
const { createRoomsRouter } = require('./routes/rooms');
const { setupWebSocket } = require('./ws');
const { createStockfishPlayer } = require('./chess/stockfishPlayer');

const PORT = process.env.PORT || 3001;
const PASSKEY_SERVER_URL = process.env.PASSKEY_SERVER_URL || 'http://localhost:3000';

async function main() {
  // Initialize database
  const db = createDb();

  // Initialize Stockfish (awaited so engine is ready before accepting requests)
  let stockfishPlayer = await createStockfishPlayer();

  // Create Express app
  const app = express();

  // Middleware
  app.use(express.json());
  const corsOrigins = process.env.CORS_ORIGINS
    ? process.env.CORS_ORIGINS.split(',')
    : [/^http:\/\/localhost:\d+$/, /^http:\/\/127\.0\.0\.1:\d+$/];
  app.use(cors({
    origin: corsOrigins,
    credentials: true
  }));

  // Request logging
  app.use((req, res, next) => {
    const start = Date.now();
    res.on('finish', () => {
      const duration = Date.now() - start;
      console.log(`${req.method} ${req.originalUrl} ${res.statusCode} ${duration}ms`);
    });
    next();
  });

  // Rate limiters
  const isTest = process.env.NODE_ENV === 'test';

  const signupLimiter = rateLimit({
    windowMs: 60 * 1000, // 1 minute
    max: 5,
    standardHeaders: true,
    legacyHeaders: false,
    skip: () => isTest,
    message: { error: 'Too many signup attempts. Try again in a minute.' }
  });

  const moveLimiter = rateLimit({
    windowMs: 60 * 1000, // 1 minute
    max: 60,
    keyGenerator: (req) => req.user ? `user:${req.user.id}` : req.ip,
    standardHeaders: true,
    legacyHeaders: false,
    skip: () => isTest,
    message: { error: 'Too many moves. Slow down.' }
  });

  // Create HTTP server
  const server = http.createServer(app);

  // Setup WebSocket
  const { broadcast } = setupWebSocket(server, db);

  // Auth middleware instance
  const auth = authMiddleware(db);

  // Mount routes
  app.use('/api/auth', signupLimiter, createAuthRouter(db, { passkeyServerUrl: PASSKEY_SERVER_URL }));

  const roomsRouter = createRoomsRouter(db, {
    broadcast,
    getStockfishPlayer: () => stockfishPlayer
  });
  app.use('/api/rooms', auth, roomsRouter);

  // Apply move-specific rate limiter to move endpoint
  app.use('/api/rooms/:id/move', moveLimiter);

  // Health check
  app.get('/api/health', (req, res) => {
    res.json({
      status: 'ok',
      stockfish: !!stockfishPlayer
    });
  });

  // Room expiry: every 5 minutes, delete stale waiting rooms
  // Delete game_states first (child FK), then rooms (parent)
  const findStaleRooms = db.prepare(`
    SELECT id FROM rooms
    WHERE status = 'waiting'
    AND created_at < datetime('now', '-15 minutes')
  `);
  const deleteGameStateByRoom = db.prepare('DELETE FROM game_states WHERE room_id = ?');
  const deleteRoomById = db.prepare('DELETE FROM rooms WHERE id = ?');

  const expireStaleRooms = db.transaction(() => {
    const stale = findStaleRooms.all();
    for (const row of stale) {
      deleteGameStateByRoom.run(row.id);
      deleteRoomById.run(row.id);
    }
    return stale.length;
  });

  setInterval(() => {
    const count = expireStaleRooms();
    if (count > 0) {
      console.log(`Expired ${count} stale waiting room(s)`);
    }
  }, 5 * 60 * 1000);

  // Start server
  server.listen(PORT, () => {
    console.log(`Chess server listening on http://localhost:${PORT}`);
    console.log(`WebSocket available at ws://localhost:${PORT}/api/rooms/:id/ws?token=xxx`);
  });

  // Graceful shutdown
  process.on('SIGINT', () => {
    console.log('\nShutting down...');
    if (stockfishPlayer) stockfishPlayer.terminate();
    db.close();
    server.close();
    process.exit(0);
  });
}

main().catch(err => {
  console.error('Failed to start server:', err);
  process.exit(1);
});

{
  "name": "chess-server",
  "version": "1.0.0",
  "type": "commonjs",
  "description": "Chess game server with REST API and WebSocket",
  "main": "index.js",
  "scripts": {
    "dev": "node --watch index.js",
    "start": "node index.js",
    "test": "node test.js"
  },
  "dependencies": {
    "better-sqlite3": "^11.0.0",
    "cors": "^2.8.5",
    "express": "^4.21.0",
    "express-rate-limit": "^7.4.0",
    "uuid": "^10.0.0",
    "ws": "^8.18.0"
  }
}

const Database = require('better-sqlite3');
const path = require('path');

const DB_PATH = process.env.CHESS_DB_PATH || path.join(__dirname, 'chess.db');

function createDb() {
  const db = new Database(DB_PATH);

  // Enable WAL mode for better concurrent read performance
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');

  // Create tables
  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      token_hash TEXT UNIQUE,
      token_expires_at TEXT,
      passkey_address TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS rooms (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      invite_code TEXT UNIQUE NOT NULL,
      white_user_id INTEGER REFERENCES users(id),
      black_user_id INTEGER REFERENCES users(id),
      status TEXT NOT NULL DEFAULT 'waiting',
      is_stockfish INTEGER NOT NULL DEFAULT 0,
      stockfish_level INTEGER DEFAULT NULL,
      result TEXT DEFAULT NULL,
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS game_states (
      room_id INTEGER PRIMARY KEY REFERENCES rooms(id),
      board TEXT NOT NULL,
      current_turn TEXT NOT NULL DEFAULT 'white',
      move_history TEXT NOT NULL DEFAULT '[]',
      en_passant_target INTEGER DEFAULT NULL,
      moved_pieces TEXT NOT NULL DEFAULT '[]',
      half_move_clock INTEGER NOT NULL DEFAULT 0,
      position_history TEXT NOT NULL DEFAULT '[]',
      updated_at TEXT DEFAULT (datetime('now'))
    );

    CREATE INDEX IF NOT EXISTS idx_rooms_invite_code ON rooms(invite_code);
    CREATE INDEX IF NOT EXISTS idx_users_token_hash ON users(token_hash);
  `);

  return db;
}

module.exports = { createDb };

