1	const express = require('express');
2	const { v4: uuidv4 } = require('uuid');
3	const crypto = require('crypto');
4	
5	const TOKEN_TTL_DAYS = 30;
6	
7	function hashToken(token) {
8	  return crypto.createHash('sha256').update(token).digest('hex');
9	}
10	
11	function createAuthRouter(db, { passkeyServerUrl } = {}) {
12	  const router = express.Router();
13	
14	  const insertUser = db.prepare(
15	    'INSERT INTO users (username, token_hash, token_expires_at) VALUES (?, ?, datetime(\'now\', ?))'
16	  );
17	  const findByUsername = db.prepare('SELECT id, username, token_hash FROM users WHERE username = ?');
18	  const findByTokenHash = db.prepare(
19	    'SELECT id, username, token_hash, token_expires_at, passkey_address FROM users WHERE token_hash = ?'
20	  );
21	  const findByPasskey = db.prepare(
22	    'SELECT id, username, token_hash, token_expires_at, passkey_address FROM users WHERE passkey_address = ?'
23	  );
24	  const insertPasskeyUser = db.prepare(
25	    'INSERT INTO users (username, token_hash, token_expires_at, passkey_address) VALUES (?, ?, datetime(\'now\', ?), ?)'
26	  );
27	  const updateToken = db.prepare(
28	    'UPDATE users SET token_hash = ?, token_expires_at = datetime(\'now\', ?) WHERE id = ?'
29	  );
30	  const revokeToken = db.prepare(
31	    'UPDATE users SET token_hash = NULL, token_expires_at = NULL WHERE id = ?'
32	  );
33	
34	  // POST /api/auth/signup — agent/bot account creation
35	  router.post('/signup', (req, res) => {
36	    const { username } = req.body;
37	
38	    if (!username || typeof username !== 'string') {
39	      return res.status(400).json({ error: 'Username is required' });
40	    }
41	
42	    const trimmed = username.trim();
43	
44	    if (trimmed.length < 3 || trimmed.length > 32) {
45	      return res.status(400).json({ error: 'Username must be 3-32 characters' });
46	    }
47	
48	    if (!/^[a-zA-Z0-9-]+$/.test(trimmed)) {
49	      return res.status(400).json({ error: 'Username may only contain letters, numbers, and hyphens' });
50	    }
51	
52	    const existing = findByUsername.get(trimmed);
53	    if (existing) {
54	      return res.status(409).json({ error: 'Username already taken' });
55	    }
56	
57	    const token = uuidv4();
58	    const tokenHash = hashToken(token);
59	    const ttl = `+${TOKEN_TTL_DAYS} days`;
60	
61	    try {
62	      insertUser.run(trimmed, tokenHash, ttl);
63	      res.status(201).json({ token, username: trimmed, expiresInDays: TOKEN_TTL_DAYS });
64	    } catch (err) {
65	      if (err.code === 'SQLITE_CONSTRAINT_UNIQUE') {
66	        return res.status(409).json({ error: 'Username already taken' });
67	      }
68	      throw err;
69	    }
70	  });
71	
72	  // POST /api/auth/token — bridge for passkey users (requires credentialId verification)
73	  router.post('/token', async (req, res) => {
74	    const { passkeyAddress, username, credentialId } = req.body;
75	
76	    if (!passkeyAddress || typeof passkeyAddress !== 'string') {
77	      return res.status(400).json({ error: 'passkeyAddress is required' });
78	    }
79	
80	    if (!username || typeof username !== 'string') {
81	      return res.status(400).json({ error: 'username is required' });
82	    }
83	
84	    if (!credentialId || typeof credentialId !== 'string') {
85	      return res.status(400).json({ error: 'credentialId is required for verification' });
86	    }
87	
88	    const trimmedUsername = username.trim();
89	    if (trimmedUsername.length < 3 || trimmedUsername.length > 32) {
90	      return res.status(400).json({ error: 'Username must be 3-32 characters' });
91	    }
92	
93	    // Verify credentialId against passkey server
94	    if (passkeyServerUrl) {
95	      try {
96	        const verifyResp = await fetch(`${passkeyServerUrl}/api/login`, {
97	          method: 'POST',
98	          headers: { 'Content-Type': 'application/json' },
99	          body: JSON.stringify({ credentialId }),
100	        });
101	        if (!verifyResp.ok) {
102	          return res.status(403).json({ error: 'Passkey verification failed' });
103	        }
104	        const verifyData = await verifyResp.json();
105	        // Ensure the returned address matches the claimed address
106	        if (verifyData.accountAddress !== passkeyAddress) {
107	          return res.status(403).json({ error: 'Passkey address mismatch' });
108	        }
109	      } catch (err) {
110	        console.error('Passkey server verification error:', err.message);
111	        return res.status(502).json({ error: 'Unable to verify passkey' });
112	      }
113	    }
114	
115	    // Find existing user by passkey address
116	    const existing = findByPasskey.get(passkeyAddress);
117	    if (existing) {
118	      // Rotate token on each bridge call for security
119	      const token = uuidv4();
120	      const tokenHash = hashToken(token);
121	      const ttl = `+${TOKEN_TTL_DAYS} days`;
122	      updateToken.run(tokenHash, ttl, existing.id);
123	      return res.json({ token, username: existing.username, expiresInDays: TOKEN_TTL_DAYS });
124	    }
125	
126	    // Create new user with passkey address
127	    const token = uuidv4();
128	    const tokenHash = hashToken(token);
129	    const ttl = `+${TOKEN_TTL_DAYS} days`;
130	
