import express from 'express';
import cors from 'cors';
import path from 'path';
import { config, validateConfig } from './config';
import authRoutes from './api/auth';
import transactionRoutes from './api/transactions';
import { getBlockchainService } from './services/blockchain';

const app = express();

// Middleware
app.use(cors());
app.use(express.json());

// Serve WebAuthn demo frontend
const frontendPath = path.resolve(__dirname, '../../../examples/webauthn-demo');
app.use(express.static(frontendPath));

// Request logging
app.use((req, res, next) => {
    console.log(`${new Date().toISOString()} ${req.method} ${req.path}`);
    next();
});

// API Routes
app.use('/api/auth', authRoutes);
app.use('/api/transactions', transactionRoutes);

// Health check
app.get('/health', async (req, res) => {
    try {
        const blockchain = getBlockchainService();
        const balance = await blockchain.getRelayerBalance();

        res.json({
            status: 'healthy',
            relayer: blockchain.getRelayerAddress(),
            balance: `${Number(balance) / 1e18} ETH`,
            contracts: config.contracts,
            chainId: config.chainId,
        });
    } catch (error) {
        res.status(500).json({
            status: 'unhealthy',
            error: error instanceof Error ? error.message : 'Unknown error',
        });
    }
});

// Error handler
app.use((err: Error, req: express.Request, res: express.Response, next: express.NextFunction) => {
    console.error('Unhandled error:', err);
    res.status(500).json({
        error: 'Internal server error',
        details: err.message,
    });
});

// Start server
async function main() {
    validateConfig();

    console.log('========================================');
    console.log('   login.com Relayer Service');
    console.log('========================================');
    console.log(`Chain ID: ${config.chainId}`);
    console.log(`RPC URL: ${config.rpcUrl}`);
    console.log(`AccountRegistry: ${config.contracts.accountRegistry}`);
    console.log(`SubscriptionRelayer: ${config.contracts.subscriptionRelayer}`);
    console.log('');

    try {
        const blockchain = getBlockchainService();
        const balance = await blockchain.getRelayerBalance();
        console.log(`Relayer Address: ${blockchain.getRelayerAddress()}`);
        console.log(`Relayer Balance: ${Number(balance) / 1e18} ETH`);
    } catch (error) {
        console.error('Failed to initialize blockchain service:', error);
        console.log('WARNING: Running without blockchain connection');
    }

    console.log('');
    app.listen(config.port, () => {
        console.log(`Server listening on http://localhost:${config.port}`);
        console.log('');
        console.log('Endpoints:');
        console.log('  POST /api/auth/register - Register new account');
        console.log('  GET  /api/auth/account/:userId - Get account info');
        console.log('  POST /api/transactions/challenge - Get signing challenge');
        console.log('  POST /api/transactions/execute - Execute sponsored tx');
        console.log('  GET  /health - Health check');
        console.log('');
    });
}

main().catch(console.error);

