import { Router, Request, Response } from 'express';
import { getBlockchainService } from '../services/blockchain';
import { hashUserId } from '../utils/crypto';
import { SubscriptionTier } from '../config/abis';

const router = Router();

interface RegisterRequest {
    username: string;
    userId?: string; // Optional - will be computed from username if not provided
    publicKey: {
        x: string;
        y: string;
    };
    credentialId: string;
}

// POST /api/auth/register
// Register a new user with their WebAuthn public key
router.post('/register', async (req: Request, res: Response) => {
    try {
        const { username, userId: providedUserId, publicKey, credentialId } = req.body as RegisterRequest;

        // Validate inputs
        if (!username || !publicKey?.x || !publicKey?.y) {
            return res.status(400).json({
                error: 'Missing required fields: username, publicKey.x, publicKey.y',
            });
        }

        const blockchain = getBlockchainService();

        // Compute userId from username (or use provided)
        const userId = providedUserId || hashUserId(username);
        console.log(`\n=== Registration Request ===`);
        console.log(`Username: ${username}`);
        console.log(`UserId: ${userId}`);
        console.log(`CredentialId: ${credentialId}`);

        // Check if account already exists
        const exists = await blockchain.hasAccount(userId);
        if (exists) {
            const existingAddress = await blockchain.getAccount(userId);
            console.log(`Account already exists at: ${existingAddress}`);

            // Return existing account info
            const subscription = await blockchain.getSubscription(userId);
            return res.json({
                accountAddress: existingAddress,
                userId,
                alreadyRegistered: true,
                subscription: {
                    tier: SubscriptionTier[subscription.tier] || 'NONE',
                    gasRemaining: subscription.gasRemaining.toString(),
                    isValid: subscription.isValid,
                },
            });
        }

        // Register new account
        const { accountAddress, txHash } = await blockchain.registerAccount(
            userId,
            publicKey.x,
            publicKey.y
        );

        // Grant FREE tier subscription
        const subTxHash = await blockchain.setSubscription(
            userId,
            SubscriptionTier.FREE,
            1 // 1 month
        );

        // Get subscription info
        const subscription = await blockchain.getSubscription(userId);

        console.log(`Account registered: ${accountAddress}`);
        console.log(`Subscription granted: FREE tier`);

        res.json({
            accountAddress,
            userId,
            registrationTx: txHash,
            subscriptionTx: subTxHash,
            subscription: {
                tier: 'FREE',
                gasRemaining: subscription.gasRemaining.toString(),
                isValid: subscription.isValid,
            },
        });
    } catch (error) {
        console.error('Registration error:', error);
        res.status(500).json({
            error: 'Registration failed',
            details: error instanceof Error ? error.message : 'Unknown error',
        });
    }
});

// GET /api/auth/account/:userId
// Get account info for a user
router.get('/account/:userId', async (req: Request, res: Response) => {
    try {
        const { userId } = req.params;
        const blockchain = getBlockchainService();

        const exists = await blockchain.hasAccount(userId);
        if (!exists) {
            return res.status(404).json({ error: 'Account not found' });
        }

        const [accountAddress, subscription] = await Promise.all([
            blockchain.getAccount(userId),
            blockchain.getSubscription(userId),
        ]);

        const nonce = await blockchain.getAccountNonce(accountAddress);

        res.json({
            userId,
            accountAddress,
            nonce: nonce.toString(),
            subscription: {
                tier: SubscriptionTier[subscription.tier] || 'NONE',
                gasRemaining: subscription.gasRemaining.toString(),
                isValid: subscription.isValid,
                periodEnd: subscription.periodEnd.toString(),
            },
        });
    } catch (error) {
        console.error('Get account error:', error);
        res.status(500).json({
            error: 'Failed to get account',
            details: error instanceof Error ? error.message : 'Unknown error',
        });
    }
});

export default router;

