export const config = {
    rpcUrl: process.env.RPC_URL || 'https://rpc.testnet.fluent.xyz',
    chainId: parseInt(process.env.CHAIN_ID || '20994'),

    contracts: {
        accountRegistry: process.env.ACCOUNT_REGISTRY || '0x8a15f5a8d2519d1c23750d7Cb360124c4A337C56',
